INSERT INTO tb_qnum ( qnum )
SELECT tb_qnum_un.qnum
FROM tb_qnum_un;

SELECT nz([ob_comp]) AS qcmp, nz([ob_type]) AS qtyp
FROM orders
WHERE nz([ob_type]) <>"";
UNION SELECT nz([ob_comp2]) AS qcmp, nz([ob_type2]) AS qtyp
FROM orders
WHERE nz([ob_type2]) <>"";

DELETE checks.*, checks.bdka, checks.numw
FROM checks
WHERE (((checks.bdka)=True) And ((checks.numw)=Forms!customers!numw));

DELETE checks.bdka, checks.numw
FROM checks
WHERE (((checks.bdka)=True) And ((checks.numw)=Forms!cust_checks!numw));

DELETE items_sales.*, items_sales.numw
FROM items_sales
WHERE (((items_sales.numw)=[Forms]![person_orders_list]![rnum]));

DELETE presence.*, presence.wdate AS Expr1
FROM presence
WHERE (((presence.wdate) Is Not Null And (presence.wdate)>=[Forms]![empty_tables]![fwdate] And (presence.wdate)<=[Forms]![empty_tables]![twdate]));

DELETE tb_q_checks.*, tb_q_checks.tdate
FROM tb_q_checks
WHERE (((tb_q_checks.tdate) Is Not Null And (tb_q_checks.tdate)>=[Forms]![empty_tables]![fwdate] And (tb_q_checks.tdate)<=[Forms]![empty_tables]![twdate]));

DELETE tb_date_list.*, tb_date_list.datew AS q1, nz([snif]) AS q2
FROM tb_date_list
WHERE (((tb_date_list.datew)>=Forms!Calendar_of_Attendance!fwdate And (tb_date_list.datew)<=Forms!Calendar_of_Attendance!twdate) And ((nz([snif]))=nz(Forms!Calendar_of_Attendance!qsnif)));

DELETE tb_hsapakim.*, tb_hsapakim.hdate
FROM tb_hsapakim
WHERE (((tb_hsapakim.hdate) Is Not Null And (tb_hsapakim.hdate)>=[Forms]![empty_tables]![fwdate] And (tb_hsapakim.hdate)<=[Forms]![empty_tables]![twdate]));

DELETE items_sales.*, Val(nz([qtyp])) AS q, items_sales.wdate
FROM items_sales
WHERE (((Val(nz([qtyp])))>0) And ((items_sales.wdate) Is Not Null And (items_sales.wdate)>=Forms!empty_tables!fwdate And (items_sales.wdate)<=Forms!empty_tables!twdate));

DELETE orders.*, orders.odate
FROM orders
WHERE (((orders.odate) Is Not Null And (orders.odate)>=[Forms]![empty_tables]![fwdate] And (orders.odate)<=[Forms]![empty_tables]![twdate]));

SELECT tb_credits.cn,null As kamp, tb_credits.namew, tb_credits.ordernum, tb_credits.typ, tb_credits.tpiraon, tb_credits.total, tb_credits.qtotal, tb_credits.qpay, tb_credits.qpayn
FROM tb_credits;
UNION ALL SELECT orders.cn, cust_list.kamp,Trim$([fname])+"  "+Trim$([pname]) AS namew, orders.order

SELECT tb_credits.cn, tb_credits.namew, tb_credits.ordernum, tb_credits.typ,tb_credits.odate,tb_credits.wdate, tb_credits.tpiraon, tb_credits.total, tb_credits.qtotal, tb_credits.qpay, tb_credits.qpayn
FROM tb_credits;
UNION ALL SELECT orders.cn, Trim$([fname])+"  "+Trim$([pname]) AS namew, orders

DELETE tb_graf.*, tb_graf.qnumpr, tb_graf.qnumpl, tb_graf.sw
FROM tb_graf
WHERE (((tb_graf.qnumpr) Is Null) AND ((tb_graf.qnumpl) Is Null) AND ((tb_graf.sw)=True));

SELECT [tb_q_checks].code_sapak FROM [tb_q_checks] GROUP BY [tb_q_checks].code_sapak HAVING ((([tb_q_checks].code_sapak) Is Not Null));
UNION SELECT tb_hsapakim.code_sapak
FROM tb_hsapakim
GROUP BY tb_hsapakim.code_sapak
HAVING (((tb_hsapakim.code_sapak) Is Not Null));

SELECT [tb_q_checks].snif FROM [tb_q_checks] GROUP BY [tb_q_checks].snif HAVING ((([tb_q_checks].snif) Is Not Null));
UNION SELECT tb_hsapakim.snif
FROM tb_hsapakim
GROUP BY tb_hsapakim.snif
HAVING (((tb_hsapakim.snif) Is Not Null));

SELECT qodrd1.*
FROM qodrd1;
UNION ALL SELECT qodrd2.*
FROM qodrd2;

SELECT tb_lens.part, tb_lens.wnum, tb_lens.typ
FROM tb_lens;
UNION ALL SELECT BANK_LIST.bank AS part, IIf(Val(nz([qtyp]))=10,88,99) AS wnum, IIf(Val(nz([qtyp]))=10,1,2) AS typ
FROM BANK_LIST
WHERE (((Val(nz([qtyp])))=10 Or (Val(nz([qtyp])))=11))
ORDER BY tb_lens.typ, tb_lens.wnum;

SELECT orders.ob_comp AS hevra, orders.ob_type AS degem, orders.ob_size AS godel, orders.ocolor AS color
FROM orders;
UNION SELECT orders.ob_comp2 AS hevra, orders.ob_type2 AS degem, orders.ob_size2 AS godel, orders.ocolor2 AS color
FROM orders;
